<script lang="ts">
 import {language,tr} from './i18n';
 import {templates} from './templates';
 let {onupload,ondimensions,ontemplate,oncontinue,onopen,recent,direct,ondirect}:{onupload:()=>void;ondimensions:()=>void;ontemplate:(id:string)=>void;oncontinue:()=>void;onopen:()=>void;recent:string;direct:boolean;ondirect:(value:boolean)=>void}=$props();
 let showTemplates=$state(false);
</script>
<main class="home" data-roomfit-home>
 <div class="top"><b style="display:flex;align-items:center;gap:12px"><img src="/favicon.svg" width="42" height="42" alt=""/>RoomFit <em>3D</em></b><select aria-label="界面语言 / Interface language" value={$language} onchange={e=>language.set(e.currentTarget.value as 'zh'|'en')}><option value="zh">简体中文</option><option value="en">English</option></select></div>
 <section class="intro"><span>YOUR SPACE, YOUR SCALE</span><h1>{$language==='zh'?'从你的房间开始':'Start with your room'}</h1><p>{$language==='zh'?'先建立空间，再选家具、试搭配、看效果。每一步都可以修改。':'Create your space, choose furniture and explore lighting. You can edit every step.'}</p></section>
 <div class="entrances">
  <button aria-label={$language==='zh'?'上传户型图':'Upload a floor plan'} onclick={onupload}><span>01 / PLAN</span><strong>{$language==='zh'?'上传户型图':'Upload a floor plan'}</strong><p>{$language==='zh'?'图片或 PDF · 分步校准与描墙':'Image or PDF · guided calibration and walls'}</p><b>↗</b></button>
  <button aria-label={$language==='zh'?'输入房间尺寸':'Enter room dimensions'} onclick={ondimensions}><span>02 / MEASURE</span><strong>{$language==='zh'?'输入房间尺寸':'Enter room dimensions'}</strong><p>{$language==='zh'?'适合单间 · 宽、深、层高':'For a single room · width, depth and height'}</p><b>↗</b></button>
  <button aria-label={$language==='zh'?'选择装修模板':'Choose a room template'} onclick={()=>showTemplates=!showTemplates}><span>03 / EXPLORE</span><strong>{$language==='zh'?'选择装修模板':'Choose a room template'}</strong><p>{$language==='zh'?'12 个可编辑空间 · 含 6 个电竞房':'12 editable layouts · including 6 gaming rooms'}</p><b>↗</b></button>
 </div>
 {#if showTemplates}<div class="templates">{#each templates as t}<button onclick={()=>ontemplate(t.id)}><img src={`/roomfit-templates/${t.id}.png`} alt=""/><strong>{$language==='zh'?t.name:t.en}</strong><small>{t.w/1000} × {t.d/1000} m · {$language==='zh'?'示例布局':'Example layout'}</small></button>{/each}</div>{/if}
 <section class="recent"><div><small>{$language==='zh'?'最近编辑 · 本机自动恢复':'Recent · local recovery'}</small><h2>{recent}</h2><p>{$language==='zh'?'参考尺寸需要核对；模板不代表真实住宅。':'Verify reference dimensions. Templates are illustrative layouts.'}</p></div><button onclick={oncontinue}>{$language==='zh'?'继续编辑':'Continue editing'} →</button><button onclick={onopen}>{$tr('打开')}</button></section>
 <footer><label><input type="checkbox" checked={direct} onchange={e=>ondirect(e.currentTarget.checked)}/>{$language==='zh'?'下次直接进入编辑器':'Open the editor directly next time'}</label><button onclick={oncontinue}>{$language==='zh'?'直接进入编辑器':'Go to editor'}</button><span>Links Tam · Local-first</span></footer>
</main>
<style>
 .home{height:100dvh;overflow:auto;color:#233b32;background:radial-gradient(ellipse at 90% 0,#e4ead8,transparent 48%),#f7f8f2;padding:28px clamp(24px,7vw,110px);box-sizing:border-box;font:14px 'Microsoft YaHei',sans-serif}.top{display:flex;justify-content:space-between;align-items:center}.top b{font-size:26px}.top em{font-style:normal;font-weight:400;color:#52694e}.intro{margin:48px 0 28px;max-width:720px}.intro span{font-size:10px;letter-spacing:3px;color:#586f57}h1{font-size:clamp(32px,4vw,48px);font-weight:500;letter-spacing:-1px;margin:14px 0}p{line-height:1.8;color:#536357}.entrances{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.entrances button{position:relative;min-height:200px;padding:26px;text-align:left;background:#fffef9;border:1px solid #d1dccb;border-radius:16px;color:#253d32;cursor:pointer}.entrances button:hover{border-color:#4e755a;box-shadow:0 8px 30px #254e2910}.entrances span{font-size:10px;letter-spacing:2px;color:#576c50}.entrances strong{display:block;font-size:21px;font-weight:500;margin:25px 0 6px}.entrances p{font-size:12px;margin:0}.entrances b{position:absolute;right:24px;top:22px;font-size:23px}.recent{display:flex;align-items:center;gap:12px;background:#e9eee1;margin-top:32px;padding:20px 24px;border-radius:14px}.recent div{flex:1}.recent h2{font-size:18px;font-weight:500;margin:8px 0}.recent p{font-size:11px;margin:0}button,select{font:inherit;color:#253f32;border:1px solid #c3d0bb;border-radius:7px;padding:10px 15px;background:#fffef9;cursor:pointer}footer{display:flex;align-items:center;flex-wrap:wrap;gap:20px;margin:25px 0;font-size:12px}footer span{margin-left:auto;color:#56684f}.templates{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin:22px 0}.templates button{text-align:left}.templates img{width:100%;height:130px;object-fit:contain}.templates strong,.templates small{display:block;margin:8px 0}.templates small{font-size:11px;color:#56674e}@media(max-width:760px){.entrances{grid-template-columns:1fr}.entrances button{min-height:140px}.intro{margin-top:26px}.recent{flex-wrap:wrap}}
</style>
